/**
 * Process-wide dev-mode flag.
 *
 * Channels are constructed at module import time (during discovery), before a
 * channel factory like `githubChannel()` ever sees the server's `--dev` flag.
 * `serve()` sets this flag *before* discovery so those factories can relax
 * dev-only defaults (e.g. the GitHub channel admitting loopback-forwarded
 * webhook deliveries without a signing secret). It never affects prod: outside
 * `--dev` the flag stays false and strict defaults apply.
 */
let devMode = false;
export function setDevMode(value) {
    devMode = value;
}
export function isDevMode() {
    return devMode;
}
